package week1.day1;

public class EmployeeDetails {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		 String name = "John Doe";
		 System.out.println("Employee name is:"+ name);
		 int age = 30;
		 System.out.println("Employee age is:"+ age);
		 double salary = 55000.75;
		 System.out.println("Employee salary is:"+ salary);
		 char gender = 'M';
		 System.out.println("Employee gender is:"+ gender);
		 boolean acceptTerms = true;
		 System.out.println("Employee acceptTerms:"+ acceptTerms);
		 float rating = 4.5f;
		 System.out.println("Employee rating is:"+ rating);
		 long mobileNumber = 9876543210L;
		 System.out.println("Employee mobilenumber is:"+ mobileNumber);
		 long pinCode = 56001;
		 System.out.println("Employee Pincode is:"+ pinCode);
		 int luckyNumber = 7;
		 System.out.println("Employee luckynumber is:"+ luckyNumber);
	}

}
